<script module lang="ts">
/**
 * A segmented time-of-day field with no popup (`design/components/time-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/time-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  agentMember,
  agentTime,
  eraseSegment,
  fieldSegments,
  joinSlot,
  stepSegment,
  timeDraft,
  timeFieldValue,
  typeIntoSegment,
  watchEffect,
  type Time,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/time-input.module.css'

export interface TimeInputMessages {
  empty: string
}

export interface TimeInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: Time | null
  disabled?: boolean
  /**
   * The segment list: `'minute'` is `[hh] [mm]`, and `'hour'` drops the minute segment. Seconds
   * are not offered, because no known screen edits them, and options are added only when needed.
   */
  granularity?: 'hour' | 'minute'
  /**
   * The locale decides by default, and this prop overrides it. `12` renders the dayPeriod
   * segment, and `24` never does.
   */
  hourCycle?: 12 | 24
  id?: string
  invalid?: boolean
  /**
   * Sets the segment order, the day period names and the separator.
   */
  locale?: string
  /**
   * Defaults to generic English (`Empty`). Localized hosts pass strings from their catalog.
   */
  messages?: TimeInputMessages
  /**
   * Serializes the ISO-8601 time in `Time`'s own format, such as `"09:30:00"`.
   */
  name?: string
  onChange?: (value: Time | null) => void
  /**
   * Keeps segments focusable and selectable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * `@internationalized/date`'s `Time`: a plain time of day with no date and no time zone, never
   * a JS `Date` (Calendar's law). The field edits down to its granularity. Finer fields in a
   * supplied value (seconds on a `Time` the app built) are kept unchanged, never silently set to
   * zero.
   */
  value?: Time | null
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  granularity = 'minute',
  hourCycle,
  id: idOwn,
  invalid: invalidOwn = false,
  locale,
  messages,
  name,
  onChange,
  readOnly = false,
  size = 'md',
  value,
}: TimeInputProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let browserLanguage = $state(undefined as string | undefined)
// svelte-ignore state_referenced_locally
let draft = $state(
  timeDraft(value !== undefined ? value : defaultValue, {
    locale: locale ?? browserLanguage ?? 'en-US',
    parts: granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
    hourCycle,
  }),
)
let typed = $state('')
// svelte-ignore state_referenced_locally
let reported = $state((value !== undefined ? value : defaultValue)?.toString() ?? '')
let field = $state<HTMLElement | null>(null)
const say = $derived(messages ?? { empty: 'Empty' })
const language = $derived(locale ?? browserLanguage ?? 'en-US')
const fieldOptions = $derived({
  locale: language,
  parts: granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
  hourCycle,
})
const segments = $derived(fieldSegments(draft, fieldOptions))
const kept = $derived((value !== undefined ? value : defaultValue) ?? null)
const current = $derived(timeFieldValue(draft, fieldOptions, kept))
const commit = $derived((next: ReturnType<typeof timeDraft>): void => {
  draft = next
  const after = timeFieldValue(next, fieldOptions, kept)
  const text = after?.toString() ?? ''
  if (text !== reported) {
    reported = text
    onChange?.(after)
  }
})
const segmentName = $derived((type: string): string => {
  try {
    return new Intl.DisplayNames(language, { type: 'dateTimeField' }).of(type) ?? type
  } catch {
    return type
  }
})
const moveSegment = $derived((from: EventTarget | null, step: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + step]?.focus()
})
const segmentKeys = $derived(
  (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
    if (segment.type === 'literal') return
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault()
      typed = ''
      moveSegment(
        event.currentTarget,
        (event.key === 'ArrowRight') ===
          (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
          ? 1
          : -1,
      )
      return
    }
    if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
    const editable = !disabled && !readOnly
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault()
      typed = ''
      if (editable)
        commit(stepSegment(draft, segment.type, event.key === 'ArrowUp' ? 1 : -1, fieldOptions))
      return
    }
    if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault()
      typed = ''
      if (!editable) return
      if (draft[segment.type] === undefined) moveSegment(event.currentTarget, -1)
      else commit(eraseSegment(draft, segment.type, fieldOptions))
      return
    }
    if (event.key.length !== 1) return
    event.preventDefault()
    if (editable)
      ((key: string): void => {
        const next = typeIntoSegment(draft, segment.type, typed, key, fieldOptions)
        typed = next.typed
        commit(next.draft)
        if (next.advance) moveSegment(event.currentTarget, 1)
      })(event.key)
  },
)
const segmentInput = $derived(
  (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
    event.preventDefault()
    if (segment.type === 'literal' || !(!disabled && !readOnly)) return
    const data = (event as InputEvent).data ?? ''
    for (const key of data) {
      const next = typeIntoSegment(draft, segment.type, typed, key, fieldOptions)
      typed = next.typed
      commit(next.draft)
      if (next.advance) {
        moveSegment(event.currentTarget, 1)
        break
      }
    }
  },
)
const effect1 = () => {
  ;((browserLanguage = globalThis.navigator?.language),
    locale === undefined &&
      (draft = timeDraft(value !== undefined ? value : defaultValue, {
        locale: locale ?? browserLanguage ?? 'en-US',
        parts: granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
        hourCycle,
      })))
}
watchEffect(effect1)
const effect2 = () => {
  value !== undefined &&
    (value !== null || current !== null) &&
    ((draft = timeDraft(value, fieldOptions)), (reported = value?.toString() ?? ''))
}
watchEffect(effect2, { watch: () => value, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'TimeInput',
    element: () => field,
    state: () => ({
      value: current?.toString() ?? '',
      disabled: disabled,
      invalid: invalid,
      readonly: readOnly,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (readOnly) throw new Error('The field is read-only.')
            commit(timeDraft(agentTime(value, granularity), fieldOptions))
          })(),
      },
      clear: () =>
        (() => {
          if (readOnly) throw new Error('The field is read-only.')
          commit({})
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={field}
    class={styles.field}
    role="group"
    {id}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-disabled={(disabled) ? 'true' : undefined}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-readonly={(readOnly) ? '' : undefined}
    data-member="time-input"
    ><div class={styles.segments}
      >{#each segments as segment, at (`time-${segment.type}-${at}`)
        }{#if segment.type === 'literal'
          }<span class={styles.separator} aria-hidden="true">{segment.text}</span
        >{:else
          }<div
            class={styles.segment}
            role="spinbutton"
            id={`${uid}-time-${segment.type}`}
            aria-label={segmentName(segment.type)}
            aria-labelledby={(ariaLabelledby) ? `${ariaLabelledby} ${uid}-time-${segment.type}` : undefined}
            aria-describedby={ariaDescribedby}
            aria-valuenow={segment.placeholder ? undefined : segment.value}
            aria-valuemin={segment.min}
            aria-valuemax={segment.max}
            aria-valuetext={segment.placeholder ? say.empty : segment.text}
            aria-required={(ariaRequired) ? 'true' : undefined}
            aria-readonly={(readOnly) ? 'true' : undefined}
            aria-disabled={(disabled) ? 'true' : undefined}
            aria-invalid={(invalid) ? 'true' : undefined}
            contenteditable={(!disabled && !readOnly) ? 'true' : undefined}
            inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
            spellcheck="false"
            tabindex={(disabled ? undefined : '0') as never}
            data-segment={segment.type}
            data-placeholder={(segment.placeholder) ? '' : undefined}
            data-disabled={(disabled) ? '' : undefined}
            onfocus={() => { typed = '' }}
            onkeydown={(event) => { segmentKeys(event, segment) }}
            onbeforeinput={(event) => { segmentInput(event, segment) }}
            >{segment.text
          }</div
        >{/if
      }{/each
    }</div
    >{#if name !== undefined
      }<input
        type="hidden"
        {name}
        value={current?.toString() ?? ''}
        disabled={(disabled) ? true : undefined}
    />{/if
  }</div
>{/if
}{@render joined.end?.()}
